function createBaseCameraPoint(): CameraPoint {
  return { existence_probability: 0, point: undefined, point_rmse: undefined };
}

export const CameraPoint: MessageFns<CameraPoint> = {
  encode(message: CameraPoint, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.existence_probability !== undefined && message.existence_probability !== 0) {
      writer.uint32(9).double(message.existence_probability);
    }
    if (message.point !== undefined) {
      Spherical3d.encode(message.point, writer.uint32(18).fork()).join();
    }
    if (message.point_rmse !== undefined) {
      Spherical3d.encode(message.point_rmse, writer.uint32(26).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): CameraPoint {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    let end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseCameraPoint();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 9) {
            break;
          }

          message.existence_probability = reader.double();
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.point = Spherical3d.decode(reader, reader.uint32());
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.point_rmse = Spherical3d.decode(reader, reader.uint32());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): CameraPoint {
    return {
      existence_probability: isSet(object.existence_probability) ? globalThis.Number(object.existence_probability) : 0,
      point: isSet(object.point) ? Spherical3d.fromJSON(object.point) : undefined,
      point_rmse: isSet(object.point_rmse) ? Spherical3d.fromJSON(object.point_rmse) : undefined,
    };
  },

  toJSON(message: CameraPoint): unknown {
    const obj: any = {};
    if (message.existence_probability !== undefined) {
      obj.existence_probability = message.existence_probability;
    }
    if (message.point !== undefined) {
      obj.point = Spherical3d.toJSON(message.point);
    }
    if (message.point_rmse !== undefined) {
      obj.point_rmse = Spherical3d.toJSON(message.point_rmse);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<CameraPoint>, I>>(base?: I): CameraPoint {
    return CameraPoint.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<CameraPoint>, I>>(object: I): CameraPoint {
    const message = createBaseCameraPoint();
    message.existence_probability = object.existence_probability ?? 0;
    message.point = (object.point !== undefined && object.point !== null)
      ? Spherical3d.fromPartial(object.point)
      : undefined;
    message.point_rmse = (object.point_rmse !== undefined && object.point_rmse !== null)
      ? Spherical3d.fromPartial(object.point_rmse)
      : undefined;
    return message;
  },
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function longToNumber(int64: { toString(): string }): number {
  const num = globalThis.Number(int64.toString());
  if (num > globalThis.Number.MAX_SAFE_INTEGER) {
    throw new globalThis.Error("Value is larger than Number.MAX_SAFE_INTEGER");
  }
  if (num < globalThis.Number.MIN_SAFE_INTEGER) {
    throw new globalThis.Error("Value is smaller than Number.MIN_SAFE_INTEGER");
  }
  return num;
}

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
